correct_example.code:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract CrossChainBridgeFixed {
    mapping(string => string) public trustedAddress;
    mapping(string => address) public tokenAddresses;
    mapping(string => uint8) public tokenDecimals;

    function setTrustedAddress(string memory chain, string memory address_, string memory expectedSourceChain) external {
        require(keccak256(bytes(chain)) == keccak256(bytes(expectedSourceChain)), "chain mismatch");
        trustedAddress[chain] = address_;
    }

    function callContractWithToken(
        string memory destinationChain,
        string memory destinationContractAddress,
        bytes memory payload,
        string memory symbol,
        uint256 amount,
        address refundAddress,
        uint256 deadline
    ) external {
        require(block.timestamp <= deadline, "expired");
        uint256 normalized = amount * 10**(18 - tokenDecimals[symbol]);
        IERC20(tokenAddresses[symbol]).safeTransferFrom(msg.sender, address(this), normalized);
        emit ContractCallWithToken(refundAddress, destinationChain, destinationContractAddress, keccak256(payload), payload, symbol, normalized, deadline);
    }

    function _getApprovalHash(
        bytes32 commandId,
        string memory sourceChain,
        string memory sourceAddress,
        bytes memory contractAddress, // bytes supports non-EVM
        bytes32 payloadHash,
        string memory symbol,
        uint256 normalizedAmount
    ) internal pure returns (bytes32) {
        return keccak256(abi.encode(commandId, sourceChain, sourceAddress, contractAddress, payloadHash, symbol, normalizedAmount));
    }

    function executeWithToken(
        bytes32 commandId,
        string memory sourceChain,
        string memory sourceAddress,
        bytes memory payload,
        string memory symbol,
        uint256 normalizedAmount
    ) external {
        uint256 currentBal = IERC20(tokenAddresses[symbol]).balanceOf(address(this));
        require(currentBal >= normalizedAmount, "insufficient balance");
        IERC20(tokenAddresses[symbol]).safeTransfer(msg.sender, normalizedAmount);
    }
}
